<template><div class="login-page"><div class="login-card"><div class="logo"><span>✓</span><div><b><i>PK</i>Takip</b><small>Periyodik Kontrol Takip</small></div></div><h1>Yönetim Paneli</h1><p>Süper admin hesabınızla giriş yapın.</p><form @submit.prevent="submit"><label>E-posta</label><InputText v-model="email" type="email" placeholder="admin@ornek.com" autocomplete="email" /><label>Şifre</label><Password v-model="password" :feedback="false" toggleMask placeholder="Şifreniz" autocomplete="current-password" /><Message v-if="error" severity="error" :closable="false">{{ error }}</Message><Button type="submit" label="Giriş Yap" icon="pi pi-arrow-right" iconPos="right" class="pk-primary login-button" :loading="loading" /></form></div></div></template>
<script setup lang="ts">definePageMeta({layout:false});const email=ref('');const password=ref('');const error=ref('');const loading=ref(false);const {login}=useAuth();const submit=async()=>{error.value='';loading.value=true;try{await login(email.value,password.value);await navigateTo('/customers')}catch(e:any){error.value=e?.data?.message||e?.message||'Giriş yapılamadı.'}finally{loading.value=false}}</script>
<style scoped>.login-page{min-height:100vh;display:grid;place-items:center;background:linear-gradient(135deg,#111827 0%,#111827 48%,#ffc107 48%,#ffc107 100%);padding:24px}.login-card{width:min(430px,100%);background:#fff;border-radius:18px;padding:38px;box-shadow:0 24px 70px #0003}.logo{display:flex;align-items:center;gap:12px;margin-bottom:34px}.logo>span{display:grid;place-items:center;width:48px;height:48px;border-radius:12px;background:#ffc107;color:#111827;font-size:31px;font-weight:800}.logo b{display:block;font-size:24px;color:#111827}.logo i{font-style:normal;color:#ffc107}.logo small{color:#64748b;font-size:11px}.login-card h1{margin:0 0 6px;color:#111827}.login-card p{margin:0 0 26px;color:#64748b}form{display:flex;flex-direction:column;gap:9px}label{font-size:13px;font-weight:600;color:#374151;margin-top:7px}.p-inputtext,.p-password,.p-password-input{width:100%}.login-button{margin-top:14px;width:100%;height:46px}</style>
